-- 0128 — THE CATERING LECHÓN, AND HOW LONG EACH DISH ACTUALLY TAKES.
--
-- Two things the 9/26 plan still got wrong after 0127.
--
-- 1. THE LECHÓN WAS THE ADULT DAY CARE'S. The only lechón asado in the HUB is the one written for
--    the Boca Raton contract — 3 oz of shredded pork with beans, rice, applesauce and milk, the
--    portion the dietitian is signing. Añejo sells it at 6 oz at an event. The plan flagged the
--    mismatch honestly but had nothing else to offer. Now it does, and matchRecipe prefers a
--    recipe with no program_key, because a contract portion is not a catering portion.
--
-- 2. NOTHING KNEW A ROAST TAKES EIGHT HOURS. With no time on file the plan gave the pernil the
--    fallback allowance — 45 minutes, on Saturday afternoon, for a 7 p.m. service. A recipe that
--    breaks the schedule it feeds is not a finished recipe, so recipes now carry their own
--    cook_minutes (per their 45-unit basis), and the kitchen's measured time still overrides it.
--
--    They also carry prep_lead_minutes: the make-ahead step that has to START before cooking can.
--    A 24-hour marinade, beans soaked overnight, a croqueta mix chilled four hours — every one of
--    them is a way Saturday fails quietly on Thursday. The plan now puts each on the calendar.
--
-- Additive. The lechón is a DRAFT like the other six: written from standard Cuban practice and
-- Añejo's own quoted portion, not transcribed from the kitchen. The cook confirms it.
-- Apply: wrangler d1 execute anejo --remote --file=migrations/0128_catering_lechon.sql

ALTER TABLE recipes ADD COLUMN cook_minutes       INTEGER;  -- to make one batch at this recipe's basis
ALTER TABLE recipes ADD COLUMN prep_lead_minutes  INTEGER;  -- how long BEFORE cooking the make-ahead step starts
ALTER TABLE recipes ADD COLUMN prep_lead_label    TEXT;
ALTER TABLE recipes ADD COLUMN prep_lead_label_es TEXT;

INSERT OR IGNORE INTO recipes (id, name, summary, ingredients, steps, tags, status, created_at, updated_at, name_es, summary_es, ingredients_es, steps_es, portion, portion_es, cook_minutes, prep_lead_minutes, prep_lead_label, prep_lead_label_es) VALUES ('rcp_cat_lechon', 'Roast pork — Lechón asado', 'Whole pork shoulder marinated a full day in mojo and roasted slow, then crackled. Written for 45 portions of 6 oz — the catering portion, not the 3 oz the adult day care contract is signed for.', '[{"item": "Bone-in pork shoulder (pernil), skin on", "qty": "30 lb"}, {"item": "Sour orange juice (or 2 parts orange to 1 part lime)", "qty": "2 qt"}, {"item": "Garlic, mashed to a paste", "qty": "3 cups"}, {"item": "Yellow onion, sliced", "qty": "4 lb"}, {"item": "Dried oregano", "qty": "½ cup"}, {"item": "Ground cumin", "qty": "¼ cup"}, {"item": "Kosher salt", "qty": "1 cup"}, {"item": "Black pepper, coarse", "qty": "¼ cup"}, {"item": "Bay leaves", "qty": "8"}, {"item": "Olive oil", "qty": "2 cups"}, {"item": "Dry white wine", "qty": "2 cups"}]', '["THE DAY BEFORE. Score the skin in a diamond pattern, cutting through the fat but not into the meat. Stab the meat all over with a knife tip so the mojo gets inside — a pernil marinated only on the surface tastes of nothing in the middle.", "Make the mojo: mash the garlic with the salt into a paste, then whisk in the sour orange, oregano, cumin, pepper, oil and wine.", "Rub the mojo into every cut and under the skin. Bury the onion and bay around it. Cover and marinate IN THE REFRIGERATOR at 41°F or below for 24 hours, never on the counter. Turn it once.", "ROASTING DAY. Take it out 1 hour ahead so it is not fridge-cold going in. Set it skin up in a deep pan with the marinade and 2 cups of water.", "Cover tight with foil and roast at 300°F for about 6 hours, until a thermometer in the thickest part away from the bone reads 195°F. It is not done at 145°F — that is the safe minimum, and this dish needs 195°F to pull apart.", "Uncover, pour off and reserve the pan juices, and roast at 450°F for 20 to 30 minutes until the skin blisters and crackles. Watch it — it goes from chicharrón to burnt in minutes.", "Rest 30 minutes before touching it. Cutting early loses the juice onto the board.", "Pull the meat, chop the crackling separately and keep it crisp. Skim the fat off the reserved juices and moisten the meat with them — this is what stops it drying out in the chafer.", "Hold at 135°F or above. Put the crackling on AT SERVICE, not in the pan."]', '["catering", "cuban", "needs_kitchen_review"]', 'draft', 1790078400000, 1790078400000, 'Lechón asado', 'Pernil entero marinado un día completo en mojo y horneado lento, con el cuero tostado al final. Escrita para 45 porciones de 6 oz — la porción de catering, no las 3 oz que tiene firmado el contrato del centro de adultos.', '[{"item": "Masa de cerdo con hueso (pernil), con cuero", "qty": "30 lb"}, {"item": "Jugo de naranja agria (o 2 partes de naranja por 1 de limón)", "qty": "2 cuartos de galón"}, {"item": "Ajo machacado en pasta", "qty": "3 tazas"}, {"item": "Cebolla amarilla en rodajas", "qty": "4 lb"}, {"item": "Orégano seco", "qty": "½ taza"}, {"item": "Comino molido", "qty": "¼ taza"}, {"item": "Sal kosher", "qty": "1 taza"}, {"item": "Pimienta negra gruesa", "qty": "¼ taza"}, {"item": "Hojas de laurel", "qty": "8"}, {"item": "Aceite de oliva", "qty": "2 tazas"}, {"item": "Vino blanco seco", "qty": "2 tazas"}]', '["EL DÍA ANTES. Marque el cuero en cuadros, cortando la grasa pero sin llegar a la carne. Pinche la carne por todos lados con la punta del cuchillo para que entre el mojo — un pernil marinado solo por fuera no sabe a nada por dentro.", "Haga el mojo: machaque el ajo con la sal hasta formar pasta, luego bata con la naranja agria, el orégano, el comino, la pimienta, el aceite y el vino.", "Unte el mojo en cada corte y debajo del cuero. Acomode la cebolla y el laurel alrededor. Tape y marine EN EL REFRIGERADOR a 41°F o menos por 24 horas, nunca en el mostrador. Voltéelo una vez.", "DÍA DE HORNEAR. Sáquelo 1 hora antes para que no entre frío del refrigerador. Póngalo con el cuero hacia arriba en una bandeja honda con la marinada y 2 tazas de agua.", "Tape bien con papel de aluminio y hornee a 300°F unas 6 horas, hasta que el termómetro en la parte más gruesa lejos del hueso marque 195°F. No está listo a 145°F — ese es el mínimo seguro, y este plato necesita 195°F para deshebrarse.", "Destape, saque y guarde el jugo de la bandeja, y hornee a 450°F de 20 a 30 minutos hasta que el cuero infle y truene. Vigílelo — pasa de chicharrón a quemado en minutos.", "Repose 30 minutos antes de tocarlo. Cortarlo antes deja el jugo en la tabla.", "Deshebre la carne, pique el chicharrón aparte y manténgalo crujiente. Quite la grasa del jugo guardado y humedezca la carne con él — eso es lo que evita que se seque en la bandeja.", "Mantenga a 135°F o más. Ponga el chicharrón AL SERVIR, no en la bandeja."]', '45 portions of 6 oz cooked', '45 porciones de 6 oz cocidas', 480, 1440, 'Season and marinate the pork in mojo — it needs a full day in the refrigerator before it goes in the oven.', 'Sazone y marine el cerdo en mojo — necesita un día completo en el refrigerador antes de ir al horno.');

-- The other six, timed to the same basis.
UPDATE recipes SET cook_minutes = 120, prep_lead_minutes = 1080, prep_lead_label = 'Soak the black beans overnight, then simmer them tender — and keep the cooking liquid, it is what makes congri black.', prep_lead_label_es = 'Remoje los frijoles negros toda la noche, luego hiervalos tiernos — y guarde el caldo, es lo que hace negro al congri.' WHERE id = 'rcp_cat_congri';
UPDATE recipes SET cook_minutes = 180, prep_lead_minutes = 60, prep_lead_label = 'Soak the corn husks in hot water so they fold without cracking.', prep_lead_label_es = 'Remoje las hojas de maiz en agua caliente para que doblen sin romperse.' WHERE id = 'rcp_cat_tamales';
UPDATE recipes SET cook_minutes = 60 WHERE id = 'rcp_cat_yuca';
UPDATE recipes SET cook_minutes = 90, prep_lead_minutes = 300, prep_lead_label = 'Make the croqueta mixture and chill it hard — at least 4 hours, overnight is better. Warm mixture bursts in the fryer.', prep_lead_label_es = 'Haga la mezcla de croquetas y enfriela bien — al menos 4 horas, mejor toda la noche. La mezcla tibia revienta en el aceite.' WHERE id = 'rcp_cat_croq_sausage';
UPDATE recipes SET cook_minutes = 60, prep_lead_minutes = 150, prep_lead_label = 'Boil, cool and dress the macaroni, then refrigerate — it is finished and dressed a second time at service.', prep_lead_label_es = 'Hierva, enfrie y alinee los coditos, luego refrigere — se termina y se alina otra vez al servir.' WHERE id = 'rcp_cat_macaroni';
UPDATE recipes SET cook_minutes = 75 WHERE id = 'rcp_cat_skewers';
